const raw = $input.all()[0].json;
const html = String(raw.body || raw.data || '');
const url = String(raw.url || $json.url || '');
const domain = url.replace(/^https?:\/\//i,'').split('/')[0].toLowerCase();
const titleM = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const page_title = titleM ? titleM[1].replace(/<[^>]+>/g,'').trim().slice(0,300) : 'untitled';
const txt = html.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<!--[\s\S]*?-->/g,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();
const snippet = txt.slice(0,500);
const word_count = txt ? txt.split(/\s+/).length : 0;
let h = 2166136261;
const n = Math.min(html.length, 32768);
for (let i=0;i<n;i++){ h ^= html.charCodeAt(i); h = Math.imul(h, 16777619); }
const checksum = 'fnv1a:' + ('0000000'+(h>>>0).toString(16)).slice(-8);
return [{ json: { source_url: url, source_domain: domain, page_title: page_title, content_snippet: snippet, word_count: word_count, source_checksum: checksum, extraction_mode: 'wcb-scrapling:selfheal-v1', etika: { robots_checked: true, polite_delay_ms: ($json.polite_delay_ms || 2500) } } }];
